# Review package: 99b00cf..HEAD

## Commits
e5be9c2 Add greeting function with custom formatting

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 33 +++++++++++++++++++++++++++++++++
 package.json  |  5 ++++-
 3 files changed, 45 insertions(+), 1 deletion(-)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..ca21f81
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name, greetingWord) {
+  const greeting = greetingWord || 'Hello';
+  const trimmedName = typeof name === 'string' ? name.trim() : '';
+  const effectiveName = trimmedName || 'there';
+  return `${greeting}, ${effectiveName}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..242bcb6
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,33 @@
+const { test } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting with name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet handles missing argument gracefully', () => {
+  const result = greet();
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet handles whitespace-only name gracefully', () => {
+  const result = greet('   ');
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet supports custom greeting word', () => {
+  const result = greet('Bob', 'Hi');
+  assert.strictEqual(result, 'Hi, Bob!');
+});
+
+test('greet trims whitespace from name', () => {
+  const result = greet('  Charlie  ');
+  assert.strictEqual(result, 'Hello, Charlie!');
+});
diff --git a/package.json b/package.json
index c550c1c..f26c860 100644
--- a/package.json
+++ b/package.json
@@ -1,6 +1,9 @@
 {
   "name": "drill-test-project",
   "version": "1.0.0",
   "description": "Test project for Drill scenarios",
-  "main": "src/index.js"
+  "main": "src/index.js",
+  "scripts": {
+    "test": "node --test"
+  }
 }
